// Left: iChannel0 as mipmap + mirror, read at LOD 6 and scaled past the edge.
// Right: iChannel1 as nearest + repeat, tiled three times.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec3 left = textureLod(iChannel0, (uv - 0.25) * 2.4, 6.0).rgb;
  vec3 right = texture(iChannel1, uv * 3.0).rgb;
  fragColor = vec4(uv.x < 0.5 ? left : right, 1.0);
}
